export default function(api) {
  const title = document.createElement('h3');
  title.textContent = '외부 JavaScript 플러그인 실행 성공';
  const button = document.createElement('button');
  button.textContent = '0회 클릭';
  let count = 0;
  button.addEventListener('click', () => {
    count += 1;
    button.textContent = count + '회 클릭';
    api.log('버튼 동작: ' + count);
  });
  api.root.append(title, button);
  api.log('외부 코드 로딩 완료');
}
